package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;
import static org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeFactorizedQuoteTest.row;

import java.util.List;

import org.eclipse.rdf4j.query.algebra.EmptySet;
import org.eclipse.rdf4j.query.algebra.LeftJoin;
import org.eclipse.rdf4j.query.algebra.SingletonSet;
import org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeCostVector.Feature;
import org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeFanOutFactsTest.StatsSource;
import org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativePlanExecutionProfile.Mode;
import org.junit.jupiter.api.Test;

/** A proven empty left side with a discardable right side has no inactive materialization uncertainty. */
class NativeOptionalDiscardableEmptyCostTest {
	@Test
	void emptySourceStillChargesItsSeekWithoutInventingOptionalBuildCost() {
		StatsSource source = new StatsSource(0L);
		RowState row = row(source);
		try {
			PatternPlan left = new PatternPlan(Term.slot(0), Term.constant(7L), Term.constant(8L), Term.unbound(),
					ContextConstraint.UNRESTRICTED, false, null, "", null, 0D, source.indexAccessProfile());
			LeftJoinPlan optional = new LeftJoinPlan(left,
					new ValuesPlan(new ValuesRow[] { new ValuesRow(new int[] { 0 }, new long[] { 1L }) }), new int[0]);
			LmdbNativeCostQuote quote = LmdbNativePlanExecutionProfile.quote(optional, row, 0L, Mode.SEQUENTIAL);
			assertThat(quote.outputProvenEmpty()).isTrue();
			assertThat(quote.total().high(Feature.INDEX_SEEK))
					.as("discovering the empty left source still incurs its real access cost")
					.isPositive();
			assertThat(quote.optionalCost())
					.as("nonzero left work must not mark the discarded RHS as unpriced")
					.isEqualTo(OptionalCostCompleteness.COMPLETE);
		} finally {
			row.memoryScope.close();
		}
	}

	@Test
	void emptyDiscardableOptionalExplainOmitsInactiveUncertainty() {
		LeftJoinPlan optional = new LeftJoinPlan(EmptyPlan.INSTANCE,
				new ValuesPlan(new ValuesRow[] { new ValuesRow(new int[] { 0 }, new long[] { 1L }) }), new int[0]);
		assertThat(optional.canDiscardRight()).isTrue();
		LeftJoin logical = new LeftJoin(new EmptySet(), new SingletonSet());
		OptionalExecutionStrategy.describe(optional).explainPlanned(logical);
		assertThat(logical.getStringMetricPlanned("nativeOptionalCostCompleteness"))
				.as("an inactive RHS build must not be described as an incomplete materialization")
				.isNotNull()
				.doesNotContain("incomplete");
		assertThat(logical.getStringMetricPlanned("nativeOptionalUncertainty"))
				.as("a discarded RHS has no unpriced materialization components")
				.isNull();

		LeftJoinPlan active = new LeftJoinPlan(SingletonPlan.INSTANCE,
				new ValuesPlan(new ValuesRow[] { new ValuesRow(new int[] { 0 }, new long[] { 1L }) }), new int[0]);
		for (boolean inactiveFirst : new boolean[] { false, true }) {
			LeftJoin mixed = new LeftJoin(new EmptySet(), new SingletonSet());
			OptionalExecutionStrategy.describe(inactiveFirst ? optional : active).explainPlanned(mixed);
			OptionalExecutionStrategy.describe(inactiveFirst ? active : optional).explainPlanned(mixed);
			assertThat(mixed.getStringMetricPlanned("nativeOptionalCostCompleteness"))
					.as("an inactive sibling cannot erase an active OPTIONAL's uncertainty")
					.contains("incomplete");
			assertThat(mixed.getStringMetricPlanned("nativeOptionalUncertainty")).isNotNull();
		}
	}

	@Test
	void emptyDiscardableOptionalDoesNotReportInactiveBuildOrSpillCost() {
		RowState row = row(new StatsSource(100_000L));
		try {
			ValuesRow[] rightRows = new ValuesRow[64];
			for (int index = 0; index < rightRows.length; index++) {
				rightRows[index] = new ValuesRow(new int[] { 0 }, new long[] { index + 1L });
			}
			LeftJoinPlan optional = new LeftJoinPlan(EmptyPlan.INSTANCE, new ValuesPlan(rightRows), new int[0]);
			assertThat(optional.canDiscardRight()).as("VALUES cannot raise a query-fatal effect").isTrue();

			LmdbNativeCostQuote quote = LmdbNativePlanExecutionProfile.quote(optional, row, 0L, Mode.SEQUENTIAL);
			assertThat(quote.outputProvenEmpty()).isTrue();
			assertThat(quote.optionalCost()).as("no OPTIONAL build is active on this path")
					.isEqualTo(OptionalCostCompleteness.COMPLETE);
			assertThat(quote.total().high(Feature.HASH_BUILD_ROW)).as("no compatibility index is constructed").isZero();
			assertThat(quote.total().high(Feature.SORT_N_LOG2_N)).as("no spill/index sort is performed").isZero();
			assertThat(quote.total().high(Feature.DECODED_ROW)).as("the discardable RHS is never built").isZero();
			assertThat(quote.forSlice(1D).high(Feature.HASH_BUILD_ROW)).isZero();

			LmdbNativeCandidate<String> candidate = LmdbNativeCandidate.of("empty-optional", quote,
					() -> "empty-optional");
			LmdbNativeSelector.Ranking ranking = LmdbNativeSelector.rank(List.of(candidate),
					LmdbNativeStaticPrior.DEFAULT, 1D);
			assertThat(ranking.incompleteOptional()[0])
					.as("inactive OPTIONAL components are absent from the selected quote")
					.isNull();
		} finally {
			row.memoryScope.close();
		}
	}
}
